import type { SchemaDefinition, SchemaCollection, FieldType } from '@intijs/core/adapters';

/**
 * Generates `inti.types.ts` from the CMS schema.
 *
 * The types describe what the adapters return, not the CMS API:
 * content is always read with the adapter, and this only gives it shape.
 * That is why dates are strings (they arrive as JSON) and media accept
 * either an id or an object (each CMS returns one or the other).
 *
 * The generated file has to compile with nothing but `@intijs/core`
 * installed: a test compiles it with `tsc --strict`. It used to
 * reference a `MediaAsset` it neither declared nor imported, and a single
 * image field was enough to break compilation.
 */
export function generateTypeDefinitions(schema: SchemaDefinition): string {
    const interfaces = schema.collections.map((collection) => generateCollectionInterface(collection));
    const blockCollections = schema.collections.filter((collection) => collection.blockType);

    return `// AUTO-GENERATED BY INTI SYNC - DO NOT EDIT
// Source: ${schema.source}
// Version: ${schema.version}
// Generated at: ${new Date().toISOString()}

import type { IntiBlock } from '@intijs/core/types';

/**
 * A media item as the adapter returns it: an id or an object, depending on the
 * CMS and the field's configuration. <IntiImage> accepts both.
 */
export type IntiMedia =
    | string
    | { url?: string; alt?: string; width?: number; height?: number; [key: string]: unknown };

${interfaces.join('\n\n')}

// ============================================
// Collection Names (for type-safe references)
// ============================================

export type CollectionName =
${schema.collections.map((c) => `    | '${c.name}'`).join('\n') || "    never"};
${generateTypedBlocks(blockCollections)}
// ============================================
// Helper Types
// ============================================

export type WithId<T> = T & { id: string };
`;
}

/**
 * Types for a page's blocks: a `type → data` map and a
 * union discriminated by `type`. With it, checking `block.type` leaves
 * `block.data` typed:
 *
 *   const blocks = page.blocks as IntiTypedBlock[];
 *   if (blocks[0].type === 'hero') blocks[0].data.headline; // string
 */
function generateTypedBlocks(collections: SchemaCollection[]): string {
    if (collections.length === 0) {
        return `
// This CMS does not describe its block types in the schema, so a page's
// blocks cannot be typed.
export type IntiTypedBlock = IntiBlock;
`;
    }

    const entries = collections
        .map((collection) => `    ${JSON.stringify(collection.blockType)}: ${collection.name};`)
        .join('\n');

    return `
// ============================================
// Typed blocks
// ============================================

/** Data for each block type, by its \`IntiBlock.type\` */
export interface IntiBlockDataMap {
${entries}
}

/**
 * A page block with its data typed according to its \`type\`.
 *
 * The adapter returns \`IntiBlock[]\`; this gives it shape without changing anything at
 * runtime:
 *
 * \`\`\`ts
 * const blocks = page.blocks as IntiTypedBlock[];
 * for (const block of blocks) {
 *   if (block.type === ${JSON.stringify(collections[0].blockType)}) block.data; // typed
 * }
 * \`\`\`
 */
export type IntiTypedBlock = {
    [K in keyof IntiBlockDataMap]: Omit<IntiBlock, 'type' | 'data'> & {
        type: K;
        data: IntiBlockDataMap[K];
    };
}[keyof IntiBlockDataMap];
`;
}

function generateCollectionInterface(collection: SchemaCollection): string {
    const fields = collection.fields.map((field) => {
        const tsType = fieldTypeToTypescript(field.type);
        const optional = field.required ? '' : '?';
        const docs = [field.description, fieldTypeNote(field.type)].filter(Boolean).join(' — ');
        const jsDoc = docs ? `    /** ${docs} */\n` : '';
        return `${jsDoc}    ${safeKey(field.name)}${optional}: ${tsType};`;
    });

    const jsDoc = collection.description ? `/**\n * ${collection.description}\n */\n` : '';

    return `${jsDoc}export interface ${collection.name} {
${fields.join('\n')}
}`;
}

/** A field name with hyphens or spaces needs quotes */
function safeKey(name: string): string {
    return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name) ? name : JSON.stringify(name);
}

function fieldTypeToTypescript(type: FieldType): string {
    switch (type) {
        case 'string':
        case 'text':
        case 'richtext':
            return 'string';
        case 'number':
            return 'number';
        case 'boolean':
            return 'boolean';
        // They arrive as JSON: they are ISO strings, not Date objects. Typing them as
        // Date let `date.getTime()` compile, which fails at runtime.
        case 'date':
        case 'datetime':
            return 'string';
        case 'media':
            return 'IntiMedia';
        case 'relation':
            return 'string';
        case 'blocks':
            return 'IntiBlock[]';
        case 'json':
        case 'component':
            return 'Record<string, unknown>';
        default:
            return 'unknown';
    }
}

function fieldTypeNote(type: FieldType): string | undefined {
    switch (type) {
        case 'date':
        case 'datetime':
            return 'ISO 8601';
        case 'richtext':
            return 'HTML';
        case 'relation':
            return 'id of the related entry';
        default:
            return undefined;
    }
}
